// Get is a Messages.resx text ("" when the key is not generated).
func Get(key string) string { return texts[key] }

// Friendly is a FriendlyNames.resx text ("" when missing), as FriendlyNameManager.GetFriendlyName.
func Friendly(key string) string { return friendly[key] }

// Format is string.Format for the {0}, {1}... placeholders of these texts.
func Format(format string, args ...any) string {
	pairs := make([]string, 0, 2*len(args))
	for i, a := range args {
		pairs = append(pairs, "{"+strconv.Itoa(i)+"}", fmt.Sprint(a))
	}
	return strings.NewReplacer(pairs...).Replace(format) // one pass: an argument's own "{1}" stays as it is
}

// FailureText is Failure.ParseExceptionMessage: the friendly text of a XAPI failure (its code and parameters) and its
// short form ("-SHORT", else the text). An unknown code gives its non-empty parts joined by " - "; an
// SR_BACKEND_FAILURE whose third part is SMAPIv3 JSON gives that JSON's "error".
func FailureText(code string, params []string) (text, short string) {
	if format, ok := errorTexts[code]; ok {
		args := make([]any, len(params))
		for i, p := range params {
			args[i] = p
		}
		text = Format(format, args...)
	} else {
		var bits []string
		for _, b := range append([]string{code}, params...) {
			if b = strings.TrimSpace(b); b != "" {
				bits = append(bits, b)
			}
		}
		text = strings.Join(bits, " - ")
	}
	if strings.HasPrefix(code, "SR_BACKEND_FAILURE") && len(params) > 1 { // ParseSmapiV3Failures
		var v struct {
			Error string `json:"error"`
		}
		if json.Unmarshal([]byte(params[1]), &v) == nil && v.Error != "" {
			text = v.Error
		}
	}
	if short = errorTexts[code+"-SHORT"]; short == "" {
		short = text
	}
	return text, short
}
